using System.Collections.Generic;
using Unity.IL2CPP.CompilerServices;

namespace Hardlight
{
	// Original HLUnityUI.Runtime 0x02000069 (TypeDefIndex 11929), methods 0x060002fe..0x060002ff.
	// The UI assembly's own UIInputType enum-to-string table, separate from the
	// HLAutoGenerated tables.
	[Il2CppSetOption(Option.NullChecks, false)]
	[Il2CppSetOption(Option.ArrayBoundsChecks, false)]
	public static class HardlightEnumExtensions
	{
		private static Dictionary<UIInputType, string> UIInputTypeEnumToString =
			new Dictionary<UIInputType, string>(HardlightUIEnumComparers.UIInputTypeComparer)
			{
				{ UIInputType.DefaultController, "DefaultController" },
				{ UIInputType.Keyboard, "Keyboard" },
				{ UIInputType.MfiController, "MfiController" },
				{ UIInputType.Mouse, "Mouse" },
				{ UIInputType.NpadController, "NpadController" },
				{ UIInputType.PS4Controller, "PS4Controller" },
				{ UIInputType.PS5Controller, "PS5Controller" },
				{ UIInputType.Remote, "Remote" },
				{ UIInputType.Touch, "Touch" },
				{ UIInputType.Unknown, "Unknown" },
				{ UIInputType.Unsupported, "Unsupported" },
				{ UIInputType.XboneController, "XboneController" },
			};

		// 0x060002fe (0x1b4fec0): an unmapped value is formatted as uppercase hex and
		// cached in the table, so later lookups return the same string.
		public static string GetString(this UIInputType value)
		{
			string result;
			if (!UIInputTypeEnumToString.TryGetValue(value, out result))
			{
				result = string.Format("0x{0:X}", value);
				UIInputTypeEnumToString[value] = result;
			}
			return result;
		}
	}
}
